function BERNSTEIN_APPROXIMANT(f, n):
    coeff[i][j] <- f(i/n, j/n)  for 0 <= i,j <= n
    function APPROX(x, y):
        total <- 0
        for i in 0..n:
            bi <- C(n,i) * x^i * (1-x)^(n-i)
            for j in 0..n:
                bj <- C(n,j) * y^j * (1-y)^(n-j)
                total <- total + coeff[i][j] * bi * bj
        return total
    return APPROX

