"""Bernstein-polynomial density demonstration on the unit square [0,1]^2."""
from __future__ import annotations
import math
from typing import Callable, List


def bernstein_2d(f: Callable[[float, float], float], n: int,
                 x: float, y: float) -> float:
    """Tensor-product Bernstein approximant; a polynomial in the coordinates."""
    total: float = 0.0
    for i in range(n + 1):
        bi = math.comb(n, i) * (x ** i) * ((1.0 - x) ** (n - i))
        for j in range(n + 1):
            bj = math.comb(n, j) * (y ** j) * ((1.0 - y) ** (n - j))
            total += f(i / n, j / n) * bi * bj
    return total


def sup_error(f: Callable[[float, float], float], n: int, res: int = 11) -> float:
    grid: List[float] = [k / (res - 1) for k in range(res)]
    return max(abs(bernstein_2d(f, n, x, y) - f(x, y)) for x in grid for y in grid)


if __name__ == "__main__":
    target = lambda x, y: math.exp(x * y) + math.sin(3 * x) * math.cos(2 * y)
    for n in (4, 8, 16, 32):
        print(f"n={n:3d}  sup error = {sup_error(target, n):.6f}")

